css:
/* Invoice Header Styling */
.invoice-header {
    text-align: left;
    font-family: Arial, sans-serif;
    margin-bottom: 20px;
    border-bottom: 3px solid #3F2B96; /* Thicker line for better visibility */
    padding-bottom: 15px; /* Increased padding */
}

/* Styling for Invoice Title */
.invoice-header h3 {
    font-size: 32px; /* Slightly larger for emphasis */
    font-weight: bold;
    color: #3F2B96; /* Dark purple shade */
    text-transform: uppercase;
    margin-bottom: 8px;
}

/* Date and Time Styling */
.invoice-header .posting-date,
.invoice-header .posting-time {
    font-size: 16px;
    color: #555;
    margin: 3px 0;
}

/* Make "Date:" and "Time:" bold */
.invoice-header .posting-date strong,
.invoice-header .posting-time strong {
    font-weight: bold;
    color: #000; /* Ensuring black for label clarity */
}

/* Customer Details Styling */
.customer-details {
    font-size: 16px;
    color: #555;
    margin-bottom: 10px;
}

/* Bold labels */
.customer-details strong {
    font-weight: bold;
    color: #000; /* Black for stronger contrast */
}

/* Space between Customer Name and Due Date */
.customer-details span {
    margin-left: 180px; /* Reduced margin for better fit */
}

/* Table Styling */
.table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 20px; /* Increased margin for better separation */
}

/* Table Borders */
.table-bordered {
    border: 2px solid #3F2B96; /* Matches the invoice header color */
}

/* Table Header Styling */
.table-bordered th {
    background-color: #3F2B96; /* Dark purple header */
    color: white;
    font-size: 16px;
    font-weight: bold;
    text-align: center;
    padding: 12px; /* Increased padding for better readability */
}

/* Table Row Styling */
.table-bordered td {
    font-size: 15px;
    color: #333;
    text-align: left;
    padding: 10px; /* Increased padding */
    border: 1px solid #3F2B96;
}

/* Right-align numeric fields */
.table-bordered td.text-right {
    text-align: right;
}

/* Table Alternating Row Colors */
.table-bordered tbody tr:nth-child(even) {
    background-color: #f9f9f9; /* Softer alternating row color */
}

/* Footer Styling */
.invoice-footer {
    margin-top: 30px; /* Increased spacing */
    padding-top: 15px;
    font-family: Arial, sans-serif;
}

/* Line styling similar to header */
.footer-line {
    border: none;
    height: 2px;
    background-color: #3F2B96;
    margin-bottom: 15px; /* More space below footer line */
}

/* Footer content layout */
.footer-content {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    font-size: 16px;
    color: #555;
}

/* Left section: Subtotal and Discount */
.footer-left {
    text-align: left;
    width: 50%;
}

/* Right section: Grand Total */
.footer-right {
    text-align: right;
    width: 50%;
}

/* Styling for labels (Subtotal, Discount, Total) - BLACK */
.footer-left p strong,
.total-due-label {
    font-size: 16px;
    font-weight: bold;
    color: #000; /* Strong contrast */
}

/* Styling for amounts - PURPLE */
.footer-left p span,
.total-due-amount {
    font-size: 22px;
    font-weight: bold;
    color: #3F2B96; /* Purple for monetary values */
}

/* Responsive Design */
@media (max-width: 768px) {
    .invoice-header {
        text-align: center;
    }

    .table-bordered th,
    .table-bordered td {
        font-size: 14px; /* Smaller font for better fit */
        padding: 6px; /* Reduced padding */
    }

    .total-summary {
        text-align: center;
    }

    .footer-content {
        flex-direction: column; /* Stack footer contents */
    }

    .footer-left,
    .footer-right {
        width: 100%;
        text-align: center;
        margin-bottom: 10px;
    }

    .customer-details span {
        margin-left: 0; /* Remove margin on small screens */
    }
}
